import { randomBytes } from "crypto";
import { promises as fs } from "fs";
import * as path from "path";
import { TourKind } from "./types";

// Creation journal: one record per created Tour, under
// `<workspace>/.tours/.log/creations/`. The hook surfaces of the agents read
// it to report the Tours a response actually created; the record therefore
// carries the creation time and whatever session identity the creating
// process could observe, and nothing else.
//
// It is observability only. A record is an independent file, written
// atomically after the Tour exists, so concurrent creations never contend for
// one document; a journal that cannot be written never fails the creation and
// is never reported as one.

/** Directory of the creation records, relative to the workspace root. */
export const CREATIONS_DIRECTORY = path.join(".tours", ".log", "creations");

export const CREATION_RECORD_VERSION = 1;

export interface CreationRecord {
  version: number;
  /** Canonical workspace root the creation was requested for. */
  workspace: string;
  /** Absolute path of the written Tour file. */
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
  /** ISO timestamp of the successful write. */
  at: string;
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

export interface CreationIdentity {
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

function nonEmpty(value: string | undefined): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed === "" ? null : trimmed;
}

// The identity is read from the environment of the creating process only: a
// value CodeTour cannot observe stays null instead of being guessed. The
// explicit variables name the session, the response and the host; a host that
// exports its own session variable is used when it identifies the host, which
// is why its presence also states the host name. Both host variables were
// verified on the installed CLIs: Pi exports PI_SESSION_ID to the bash tool,
// and the Copilot CLI exports COPILOT_AGENT_SESSION_ID, whose value equals the
// `sessionId` its agentStop hook receives.
export function creationIdentity(
  env: Record<string, string | undefined> = process.env
): CreationIdentity {
  const explicitSession = nonEmpty(env.CODETOUR_SESSION_ID);
  const piSession = nonEmpty(env.PI_SESSION_ID);
  const copilotSession = nonEmpty(env.COPILOT_AGENT_SESSION_ID);
  const [sessionId, observedHost]: [string | null, string | null] =
    explicitSession !== null ? [explicitSession, null]
      : piSession !== null ? [piSession, "pi"]
        : copilotSession !== null ? [copilotSession, "copilot"]
          : [null, null];
  return {
    sessionId,
    responseId: nonEmpty(env.CODETOUR_RESPONSE_ID),
    host: nonEmpty(env.CODETOUR_HOST) ?? observedHost,
  };
}

export interface CreationRecordInput {
  workspaceRoot: string;
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
}

// Write one creation record. Returns the written file, or undefined when the
// journal is unavailable; the caller treats that as a diagnostic, never as a
// failure of the creation itself.
export async function recordCreation(
  input: CreationRecordInput,
  identity: CreationIdentity = creationIdentity()
): Promise<string | undefined> {
  const createdAt = new Date();
  const record: CreationRecord = {
    version: CREATION_RECORD_VERSION,
    workspace: input.workspaceRoot,
    tourPath: input.tourPath,
    tourTitle: input.tourTitle,
    kind: input.kind,
    at: createdAt.toISOString(),
    sessionId: identity.sessionId,
    responseId: identity.responseId,
    host: identity.host,
  };
  const directory = path.join(input.workspaceRoot, CREATIONS_DIRECTORY);
  // `<createdAtMs>-<pid>-<random>`: sortable by time, unique under concurrent
  // creations from the same process.
  const fileName = `${createdAt.getTime()}-${process.pid}-${randomBytes(4).toString("hex")}.json`;
  const target = path.join(directory, fileName);
  const temporary = path.join(directory, `.${fileName}.tmp`);
  try {
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(temporary, `${JSON.stringify(record, null, 2)}\n`, "utf8");
    await fs.rename(temporary, target);
    return target;
  } catch {
    await fs.rm(temporary, { force: true }).catch(() => undefined);
    return undefined;
  }
}

import * as fs from "fs";
import * as path from "path";
import { validateCodetourTour } from "./codetour-schema";
import { createContext } from "./context";
import {
  changedFiles,
  committedDiffIsEmpty,
  currentBranchName,
  currentHeadSha,
  isGitRepository,
  mergeBase,
  normalizeSlashes,
  readCommitAnchors,
  resolveCommit,
  uncommittedChanges,
  workspacePrefix,
} from "./git";
import { recordCreation } from "./journal";
import { OutputPathError, writeTourAtomic } from "./persistence";
import { stageCommitAnchors, validateTourProposal } from "./proposal-validation";
import {
  CreationFailure,
  CreationResult,
  CreateTourOptions,
  CreatedTour,
  TourFile,
  TourKind,
  TourStep,
  Warning,
  WorkspaceContext,
} from "./types";
import { MAX_RECOMMENDED_STEPS, orientationStepWarnings } from "./validation";

// Tour creation, free of any transport: both entry points take the
// workspace to create in and the proposal exactly as it arrived, validate it,
// apply the Git, image, Mermaid and workspace-confinement rules, write the
// Tour file atomically, and report the outcome as a value. Nothing here writes
// to a stream or reads a command line, so the command-line surface stays a thin
// adapter over these rules instead of reimplementing them.
//
// Validation always precedes the write: a rejected proposal writes no file and
// leaves any existing Tour untouched.

const CODETOUR_SCHEMA_URI = "https://aka.ms/codetour-schema";

// Fixed destinations reserved for generated Tours. They are replaced only
// after complete validation and ignored while detecting a dirty workspace (see
// git.ts).
const PROJECT_TOUR_PATH = ".tours/project.tour";
const CHANGES_TOUR_PATH = ".tours/changes.tour";

// A custom `fileName` is always confined to the `.tours` directory next to the
// reserved destinations; without one the reserved default applies.
function tourTargetPath(defaultPath: string, fileName?: string): string {
  return fileName === undefined ? defaultPath : `.tours/${fileName}`;
}

// The name of the entry point a rejection addresses: the caller's own surface
// name, or the command of that kind when the caller named none.
function surfaceName(kind: TourKind, options: CreateTourOptions): string {
  return options.surface ?? `create-${kind}-tour`;
}

function failure(code: string, message: string, issues?: CreationFailure["issues"]): CreationFailure {
  return {
    ok: false,
    code,
    message,
    ...(issues && issues.length > 0 ? { issues } : {}),
  };
}

// A written Tour as the kind-specific rules report it; the caller adds the
// kind and the workspace, then records the creation.
type WrittenTour = { ok: true } & Omit<CreatedTour, "kind" | "workspaceRoot">;
type WriteOutcome = WrittenTour | CreationFailure;

// Create a Project Tour: no Git access is required, the tour works in any
// workspace, and it is never attached to a `ref` so it remains viewable as the
// project evolves.
export async function createProjectTour(options: CreateTourOptions): Promise<CreationResult> {
  return createTour("project", options);
}

// Create a Changes Tour: analyze committed changes from the merge-base of
// `baseRef` to `headRef`. `headRef` must be the full SHA of the current HEAD;
// otherwise creation fails with STALE_HEAD to avoid a stale explanation. By
// default only committed changes are included; `includeUncommittedChanges`
// enables explaining local work.
export async function createChangesTour(options: CreateTourOptions): Promise<CreationResult> {
  return createTour("changes", options);
}

async function createTour(kind: TourKind, options: CreateTourOptions): Promise<CreationResult> {
  // The requested workspace is the boundary every rule confines to; a call may
  // only narrow it with `workspacePath`, never expand it.
  const requested = createContext(options.workspaceRoot);
  const outcome =
    kind === "project"
      ? await projectTour(options, requested)
      : await changesTour(options, requested);
  if (!outcome.ok) return outcome;

  const created: CreatedTour = { kind, workspaceRoot: requested.root, ...outcome };
  // The journal is observability: it is written once the Tour exists, and a
  // journal that cannot be written never turns a creation into a failure.
  await recordCreation({
    workspaceRoot: requested.root,
    tourPath: created.tourPath,
    tourTitle: created.title,
    kind: created.kind,
  });
  return { ok: true, ...created };
}

async function projectTour(
  options: CreateTourOptions,
  defaultContext: WorkspaceContext
): Promise<WriteOutcome> {
  const result = await validateTourProposal(
    "project",
    options.proposal,
    defaultContext,
    surfaceName("project", options)
  );
  if (!result.ok) {
    return result.rejection;
  }
  const { ctx, params, steps: finalSteps } = result.proposal;

  const warnings = [
    ...stepLimitWarnings(finalSteps),
    ...orientationStepWarnings(finalSteps),
  ];

  const title = params.title ?? "Project Overview";

  const tour: TourFile = {
    $schema: CODETOUR_SCHEMA_URI,
    title,
    ...(params.description !== undefined ? { description: params.description } : {}),
    steps: finalSteps,
  };

  const targetPath = tourTargetPath(PROJECT_TOUR_PATH, params.fileName);
  const writeFailure = await persistTour(ctx, targetPath, tour);
  if (writeFailure) {
    return writeFailure;
  }

  return {
    ok: true,
    tourPath: path.join(ctx.root, targetPath),
    title,
    stepCount: finalSteps.length,
    warnings,
  };
}

async function changesTour(
  options: CreateTourOptions,
  defaultContext: WorkspaceContext
): Promise<WriteOutcome> {
  const surface = surfaceName("changes", options);
  const result = await validateTourProposal("changes", options.proposal, defaultContext, surface);
  if (!result.ok) {
    return result.rejection;
  }
  const { ctx, params } = result.proposal;

  const baseRef = params.baseRef as string;
  const headRef = params.headRef as string;
  const includeUncommittedChanges = params.includeUncommittedChanges === true;

  // The Changes Tour depends on Git history and fails outside a repository.
  if (!(await isGitRepository(ctx))) {
    return failure(
      "GIT_REPOSITORY_REQUIRED",
      `${surface} requires a Git repository, but the configured workspace root (${ctx.root}) is not inside one. ` +
        "Select a repository with workspacePath, or point the workspace at the repository to analyze rather than at its parent directory."
    );
  }

  // The analyzed SHA must exactly match the current HEAD; otherwise the
  // explanation might not correspond to the snapshot read again.
  const currentHead = await currentHeadSha(ctx);
  if (currentHead === null) {
    return failure(
      "STALE_HEAD",
      "The repository has no commits, so there is no HEAD to analyze."
    );
  }
  if (headRef !== currentHead) {
    return failure(
      "STALE_HEAD",
      `The provided headRef ${headRef} does not match the current HEAD (${currentHead}). The analysis is stale; re-run it against the current HEAD.`
    );
  }

  // Resolve the base reference to a full commit SHA up front: only a verified
  // SHA is ever passed as a positional Git argument, so an agent-supplied
  // string can never be interpreted as a Git option.
  const resolvedBaseSha = await resolveCommit(ctx, baseRef);
  if (resolvedBaseSha === null) {
    return failure(
      "INVALID_BASE_REF",
      `Unable to resolve the base ref ${baseRef} to a commit in this repository.`
    );
  }

  let mergeBaseSha: string;
  try {
    mergeBaseSha = await mergeBase(ctx, resolvedBaseSha, headRef);
  } catch (error) {
    return failure(
      "INVALID_BASE_REF",
      `Unable to compute the merge-base between ${baseRef} and ${headRef}: ${(error as Error).message}`
    );
  }

  // Without committed changes (and without included local work), return
  // NO_CHANGES and preserve the previous Changes Tour: an empty tour never
  // replaces a useful one.
  const uncommitted = await uncommittedChanges(ctx);
  const includesLocalChanges = includeUncommittedChanges && uncommitted.length > 0;
  const staged = await stageCommitAnchors(result.proposal, {
    mergeBaseSha,
    includesLocalChanges,
  });
  if (staged.issues.length > 0) {
    return failure("INVALID_PROPOSAL", `The ${surface} arguments are invalid.`, staged.issues);
  }
  if (
    (await committedDiffIsEmpty(ctx, mergeBaseSha, headRef)) &&
    (!includeUncommittedChanges || uncommitted.length === 0)
  ) {
    return failure(
      "NO_CHANGES",
      `No committed changes between the merge-base of ${baseRef} (${mergeBaseSha}) and ${headRef}. The previous tour file was preserved.`
    );
  }

  // Uncommitted changes are excluded by default with a warning, or explicitly
  // included; in that case the Tour has no `ref` and reports that the result
  // describes a non-reproducible local state.
  const warnings: Warning[] = [];
  if (includesLocalChanges) {
    warnings.push({
      code: "UNCOMMITTED_CHANGES_INCLUDED",
      message:
        "Uncommitted changes were explicitly included; the tour describes a local state that is not reproducible from Git.",
    });
  } else if (uncommitted.length > 0) {
    warnings.push({
      code: "UNCOMMITTED_CHANGES_EXCLUDED",
      message: `${uncommitted.length} uncommitted change(s) were excluded from the analysis (staged, unstaged or untracked).`,
    });
  }

  const finalSteps = staged.steps.map((step) => {
    const { display, baseFile, ...ordinaryStep } = step;
    if (includesLocalChanges || step.file === undefined) return ordinaryStep;
    const file = path.posix.normalize(normalizeSlashes(step.file));
    return { ...ordinaryStep, file, display: "diff" as const, baseFile: staged.renames.get(file) };
  });
  warnings.push(...stepLimitWarnings(finalSteps));

  // A Changes Tour must anchor at least one file the comparison actually
  // modified. The former advisory warning let a whole tour describe a change
  // set without ever pointing at it, so the agent had to regenerate. Deleted
  // files cannot host an anchor; when every changed file is gone (a
  // deletion-only branch), the rule has nothing to anchor and stays satisfied.
  const anchorableChangedFiles = await changedFilesAvailableToAnchor(
    ctx,
    mergeBaseSha,
    headRef,
    uncommitted,
    includeUncommittedChanges
  );
  if (
    anchorableChangedFiles.length > 0 &&
    !finalSteps.some(
      (step) =>
        step.file !== undefined &&
        anchorableChangedFiles.includes(normalizeSlashes(step.file))
    )
  ) {
    const listed = anchorableChangedFiles.slice(0, 5).join(", ");
    const suffix =
      anchorableChangedFiles.length > 5
        ? ` and ${anchorableChangedFiles.length - 5} more`
        : "";
    return failure(
      "MISSING_CHANGED_FILE_ANCHOR",
      `No step anchors a file modified by these changes. Add at least one step ` +
        `with file and a line or a short unique pattern on one of: ${listed}${suffix}. ` +
        "The previous tour file was preserved.",
      [
        {
          path: "steps",
          message:
            `must anchor at least one changed file (${listed}${suffix}) ` +
            "with file plus line or pattern; deletion-only changes are exempt",
        },
      ]
    );
  }

  const title = params.title ?? (await defaultChangesTitle(ctx, headRef));
  // Enrich the description automatically with the provenance, base, and head
  // so the reader always knows the analyzed scope.
  const provenance = includesLocalChanges
    ? `Generated from the merge-base of \`${baseRef}\` (\`${mergeBaseSha}\`) to \`${headRef}\`, including uncommitted changes (non-reproducible local state).`
    : `Generated from the merge-base of \`${baseRef}\` (\`${mergeBaseSha}\`) to \`${headRef}\`.`;
  const description =
    params.description !== undefined
      ? `${params.description}\n\n${provenance}`
      : provenance;

  const tour: TourFile = {
    $schema: CODETOUR_SCHEMA_URI,
    title,
    description,
    ...(!includesLocalChanges ? { ref: headRef, baseRef: mergeBaseSha } : {}),
    steps: finalSteps,
  };

  // HEAD may advance during the Git reads above. Reading it again at the last
  // moment prevents stale analysis from replacing the previous Changes Tour.
  const headImmediatelyBeforePersistence = await currentHeadSha(ctx);
  if (headImmediatelyBeforePersistence !== headRef) {
    return failure(
      "STALE_HEAD",
      headImmediatelyBeforePersistence === null
        ? "The repository no longer has a HEAD to persist this analysis against. The previous tour file was preserved."
        : `The provided head ${headRef} no longer matches the current HEAD (${headImmediatelyBeforePersistence}). The analysis became stale before persistence; re-run it against the current HEAD.`
    );
  }

  const targetPath = tourTargetPath(CHANGES_TOUR_PATH, params.fileName);
  const writeFailure = await persistTour(ctx, targetPath, tour);
  if (writeFailure) {
    return writeFailure;
  }

  return {
    ok: true,
    tourPath: path.join(ctx.root, targetPath),
    title,
    stepCount: finalSteps.length,
    warnings,
  };
}

// Non-blocking warning when a Tour exceeds fifteen steps.
function stepLimitWarnings(steps: TourStep[]): Warning[] {
  if (steps.length <= MAX_RECOMMENDED_STEPS) {
    return [];
  }
  return [
    {
      code: "STEP_LIMIT_EXCEEDED",
      message: `The tour has ${steps.length} steps; the recommended maximum is ${MAX_RECOMMENDED_STEPS}.`,
    },
  ];
}

// Validate the generated Tour against the general CodeTour schema, then write
// it atomically. If validation fails, the previous file remains intact.
async function persistTour(
  ctx: WorkspaceContext,
  relativePath: string,
  tour: TourFile
): Promise<CreationFailure | null> {
  const schemaResult = validateCodetourTour(tour);
  if (!schemaResult) {
    return failure(
      "SCHEMA_VALIDATION_FAILED",
      "The generated tour did not validate against the CodeTour schema."
    );
  }
  try {
    await writeTourAtomic(ctx, relativePath, serializeTour(tour));
  } catch (error) {
    if (error instanceof OutputPathError) {
      return failure("OUTPUT_PATH_ESCAPES_WORKSPACE", error.message);
    }
    throw error;
  }
  return null;
}

// Files modified by the committed diff, converted to paths relative to the
// workspace (the workspace may be a repository subdirectory).
async function changedFilesInWorkspace(
  ctx: WorkspaceContext,
  mergeBaseSha: string,
  headRef: string
): Promise<string[]> {
  const files = await changedFiles(ctx, mergeBaseSha, headRef);
  const prefix = normalizeSlashes(await workspacePrefix(ctx));
  return files
    .map(normalizeSlashes)
    .filter((file) => file.startsWith(prefix))
    .map((file) => file.slice(prefix.length));
}

// Changed paths that a step can actually anchor. A committed-only tour reads
// anchors from the analyzed commit, so a file deleted there is not anchorable
// even if a working-tree copy exists; an included-local-changes tour reads the
// workspace, so only a regular file present on disk qualifies. The distinction
// is what keeps a deletion-only branch from being rejected.
async function changedFilesAvailableToAnchor(
  ctx: WorkspaceContext,
  mergeBaseSha: string,
  headRef: string,
  uncommitted: ReadonlyArray<{ path: string }>,
  includesLocalChanges: boolean
): Promise<string[]> {
  const changed = await changedFilesInWorkspace(ctx, mergeBaseSha, headRef);
  if (includesLocalChanges) {
    for (const entry of uncommitted) {
      if (!changed.includes(entry.path)) {
        changed.push(entry.path);
      }
    }
    return changed.filter((file) => {
      try {
        return fs.statSync(path.resolve(ctx.root, file)).isFile();
      } catch {
        return false;
      }
    });
  }
  if (changed.length === 0) return [];
  const anchors = await readCommitAnchors(ctx, headRef, []);
  return changed.filter(
    (file) =>
      anchors.get(path.posix.normalize(normalizeSlashes(file)))?.kind === "file"
  );
}

// Default Changes Tour title: "Changes on <branch>", falling back to the short
// SHA when HEAD is detached.
async function defaultChangesTitle(
  ctx: WorkspaceContext,
  headRef: string
): Promise<string> {
  const branch = await currentBranchName(ctx);
  if (branch && branch !== "HEAD") {
    return `Changes on ${branch}`;
  }
  return `Changes at ${headRef.slice(0, 7)}`;
}

function serializeTour(tour: TourFile): string {
  return JSON.stringify(tour, null, 2) + "\n";
}

import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import {
  readCreations,
  selectCreated,
  summaryLines,
  tokenLine,
  tokenReading,
} from "../lib/journal.mjs";
import {
  TERMINAL_OPTION,
  VSCODE_OPTION,
  existingTourReader,
  interactiveSession,
  openingOptions,
  openingQuestion,
  playInTerminal,
  readerInvocation,
  runTerminalReader,
  vscodeCommand,
} from "../lib/reader.mjs";

// CodeTour for Pi.
//
// The package is two surfaces:
//
//  - the `codetour-generate` skill, which makes the agent create a Tour with
//    the CodeTour CLI (`codetour create-project-tour` / `create-changes-tour`)
//    from the workspace it is in: no MCP server and no CodeTour checkout;
//  - this extension, which reads the creation journal when a response settles
//    and reports, once, the Tours that response created and the response's
//    token reading.
//
// The report is purely informative (DESIGN §4): it never blocks, never asks for
// a continuation, never calls a model, never writes Tour content, and never
// changes the agent's exit status. It has nothing to say when no creation is
// attributed to the response.

const PACKAGE_ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const SKILL_COMMAND = "/skill:codetour-generate";

type RunKind = "project" | "changes";
type ReviewMode = "neutral" | "critical";

interface Launcher {
  command: string;
  args: string[];
}

interface CreationRecord {
  workspace: string;
  tourPath: string;
  tourTitle: string;
  kind: RunKind;
  at: string;
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

/**
 * The CLI that serves the session. `codetour --install pi` writes
 * `launcher.json` next to this file with the absolute runtime and script of the
 * installing CLI, so a stale `codetour` on PATH cannot serve an older build.
 * Without it (a checkout run by hand), PATH is the documented fallback.
 */
async function installedLauncher(): Promise<Launcher | undefined> {
  try {
    const raw = await fs.readFile(path.join(PACKAGE_ROOT, "launcher.json"), "utf8");
    const parsed = JSON.parse(raw) as { command?: unknown; args?: unknown };
    if (
      typeof parsed.command === "string" &&
      parsed.command !== "" &&
      Array.isArray(parsed.args) &&
      parsed.args.every((arg) => typeof arg === "string")
    ) {
      return { command: parsed.command, args: parsed.args as string[] };
    }
  } catch {
    // No managed launcher: PATH is the documented fallback.
  }
  return undefined;
}

/**
 * The argv words of the CLI to call: the recorded launcher when installed,
 * `codetour` from PATH otherwise. Every surface here calls a top-level
 * subcommand, and `launcher.json` records no subcommand at all.
 */
function cliWords(launcher: Launcher | undefined): string[] {
  return launcher ? [launcher.command, ...launcher.args] : ["codetour"];
}

async function realWorkspace(cwd: string): Promise<string | undefined> {
  try {
    const real = await fs.realpath(cwd);
    const stat = await fs.stat(real);
    return stat.isDirectory() ? real : undefined;
  } catch {
    return undefined;
  }
}

interface GenerationChoices {
  type?: RunKind;
  reviewMode?: ReviewMode;
  request: string;
}

// `/codetour generate`, `/codetour project`, `/codetour changes critical explain the
// renderer`, `/codetour generate changes neutral <phrase>`. Anything that is
// not a recognised choice word belongs to the user's request and is forwarded
// verbatim.
function parseChoices(raw: string): GenerationChoices {
  const words = raw.trim().split(/\s+/).filter(Boolean);
  let index = 0;
  if (words[0] === "generate") index = 1;
  let type: RunKind | undefined;
  const head = words[index];
  if (head === "project" || head === "changes") {
    type = head;
    index += 1;
  }
  let reviewMode: ReviewMode | undefined;
  if (type === "changes") {
    const mode = words[index];
    if (mode === "neutral" || mode === "critical") {
      reviewMode = mode;
      index += 1;
    }
  }
  return { type, reviewMode, request: words.slice(index).join(" ") };
}

function skillInvocation(choices: {
  type: RunKind;
  reviewMode?: ReviewMode;
  cli?: string[];
  request: string;
}): string {
  const parts = [SKILL_COMMAND, `type=${choices.type}`];
  if (choices.type === "changes" && choices.reviewMode) {
    parts.push(`reviewMode=${choices.reviewMode}`);
  }
  // The installed CLI travels as one JSON array of argv words: skill arguments
  // are free text, so a single self-delimiting token keeps a path with spaces
  // intact (DESIGN §9). Without a recorded launcher the skill uses PATH.
  if (choices.cli) parts.push(`codetour-cli=${JSON.stringify(choices.cli)}`);
  if (choices.request) parts.push(`request=${choices.request}`);
  return parts.join(" ");
}

/** The usage of the assistant messages of the last agent run of the response. */
function responseUsages(event: { messages?: unknown } | undefined): unknown[] {
  const messages = Array.isArray(event?.messages) ? event.messages : [];
  return messages
    .filter((message: any) => message?.role === "assistant")
    .map((message: any) => message.usage);
}

/**
 * Fallback reading of the same response from the session entries, used when
 * `agent_end` delivered no message. It cannot be bounded exactly, so the
 * reading is reported as approximate.
 */
function sessionUsages(ctx: ExtensionContext, since: number): unknown[] {
  const entries =
    typeof ctx.sessionManager?.getEntries === "function" ? ctx.sessionManager.getEntries() : [];
  if (!Array.isArray(entries)) return [];
  return entries
    .filter((entry: any) => entry?.type === "message" && entry.role === "assistant")
    .filter((entry: any) => {
      const at = Date.parse(entry.timestamp);
      return !Number.isFinite(at) || at >= since;
    })
    .map((entry: any) => entry.usage);
}

interface DiscoveredTour {
  id: string;
  title: string;
}

async function readTour(pi: ExtensionAPI, ctx: ExtensionContext, title: string) {
  const words = cliWords(await installedLauncher());
  const cli = { command: words[0], args: words.slice(1) };
  const workspace = await realWorkspace(ctx.cwd);
  if (!workspace) throw new Error(`${ctx.cwd} is not a usable workspace.`);

  const resolve = async (args: string[]) => {
    const invocation = readerInvocation(cli, args, workspace);
    const result = await pi.exec(invocation.command, invocation.args, { cwd: workspace });
    if (result.code !== 0) throw new Error(result.stderr.trim() || `CLI exited with code ${result.code}.`);
    return JSON.parse(result.stdout);
  };

  let selected: DiscoveredTour;
  if (title) {
    selected = await resolve([`--internal-resolve-tour=${title}`]);
  } else {
    const tours: DiscoveredTour[] = await resolve(["--internal-list-tours"]);
    if (tours.length === 0) throw new Error("No CodeTours found in this workspace.");
    const labels = tours.map((tour, index) => `${index + 1}. ${tour.title}`);
    const choice = tours.length === 1 ? labels[0] : await ctx.ui.select("Select a CodeTour", labels);
    if (choice === undefined) return;
    selected = tours[labels.indexOf(choice)];
    if (!selected) throw new Error("Invalid Tour selection.");
  }

  const { plan, command } = existingTourReader(selected.id, cli, workspace);
  const play = () => runTerminalReader(plan, command);
  const outcome = ctx.hasUI && interactiveSession()
    ? await ctx.ui.custom<Awaited<ReturnType<typeof play>>>(async (tui, _theme, _keys, done) => {
        tui.stop();
        let result;
        try {
          result = await play();
        } finally {
          tui.start();
          tui.requestRender(true);
        }
        done(result);
        return { render: () => [], invalidate: () => {} };
      })
    : await runTerminalReader(plan, command, { isInteractive: () => false });
  if (outcome.degraded) {
    ctx.ui.notify(`CodeTour: ${outcome.reason} From the workspace root (${workspace}), run: ${command}`, "warning");
  } else if (outcome.exitCode !== 0) {
    ctx.ui.notify(`CodeTour: the reader ended (${outcome.signal || outcome.exitCode}).`, "warning");
  }
}

export default function codetourPlugin(pi: ExtensionAPI) {
  // The response window of DESIGN §4: `agent_start` opens it and
  // `agent_settled` closes it. Pi exposes no response identity (#323 recon
  // §5.c), so the boundary is this instant, compared with the creation
  // records' own `at`.
  let responseStart: number | undefined;
  // The usage of the last run's assistant messages, and how many starts and
  // ends the response contained. Either can repeat or be missing on recovery.
  let runUsages: unknown[] = [];
  let runCount = 0;
  let runStarts = 0;

  // Observability must not become a chorus: one report per response window,
  // and one opening dialogue per created Tour whatever the host re-emits.
  const reportedResponses = new Set<number>();
  const offeredTours = new Set<string>();

  /**
   * The end-of-response report: the Tours this response created, then its
   * single token reading. Silent when no creation is attributed.
   */
  async function reportResponse(
    ctx: ExtensionContext,
    created: CreationRecord[],
    windowStart: number
  ): Promise<void> {
    for (const line of summaryLines(created)) {
      ctx.ui.notify(line, "info");
    }
    // The reading is exact only when it covers the whole response: a single
    // run, whose messages `agent_end` delivered. A repeated run (retry,
    // compaction retry, queued follow-up) leaves only the last one, and the
    // session entries cannot be bounded to the response at all, so both are
    // labelled approximate.
    const fromRun = runUsages.length > 0;
    const usages = fromRun ? runUsages : sessionUsages(ctx, windowStart);
    const approximate = !fromRun || runCount !== 1 || runStarts !== 1;
    ctx.ui.notify(tokenLine(tokenReading(usages, { approximate })), "info");
  }

  /**
   * The opening dialogue of ticket #242, re-pointed at the creation journal:
   * the real interactive reader in this terminal, or the Tour at its active
   * step in VS Code. Never a textual summary, never an independent window, and
   * never a second question for the same Tour.
   */
  async function offerReader(
    ctx: ExtensionContext,
    record: CreationRecord,
    workspace: string
  ): Promise<void> {
    const key = `${record.tourPath}|${record.at}`;
    if (offeredTours.has(key)) return;
    offeredTours.add(key);
    // Print and JSON modes have no dialogue to offer (ctx.hasUI === false).
    if (ctx.hasUI === false) return;
    const tour = { tourPath: record.tourPath, tourTitle: record.tourTitle, workspace };
    const question = openingQuestion(tour);
    if (!question) return;
    const choice = await ctx.ui.select(question, openingOptions());
    const words = cliWords(await installedLauncher());
    if (choice === TERMINAL_OPTION) {
      // The real reader opens immediately: the installed CLI is spawned with
      // inherited stdio — this very terminal, never an independent window — and
      // the call returns only when the reading ends. A non-interactive session
      // or a failed spawn degrades to the documented hand-over command.
      const outcome = await playInTerminal(tour, { command: words[0], args: words.slice(1) });
      if (outcome.degraded && outcome.command) {
        ctx.ui.notify(
          outcome.reason
            ? `CodeTour: ${outcome.reason} Run ${outcome.command} at the ` +
              "workspace root — the reader plays in this terminal, never an independent window."
            : `Run ${outcome.command} at the workspace root — the reader plays ` +
              "in this terminal, never an independent window.",
          "warning"
        );
      } else if (outcome.played && outcome.exitCode !== 0) {
        ctx.ui.notify(
          `CodeTour: the reader ended (${outcome.signal || outcome.exitCode}); ` +
            "the terminal is back with your session.",
          "warning"
        );
      }
    } else if (choice === VSCODE_OPTION) {
      const command = vscodeCommand(tour);
      if (!command) {
        ctx.ui.notify("CodeTour: the created Tour has no path to open in VS Code.", "warning");
        return;
      }
      try {
        const result = await pi.exec(
          words[0],
          [...words.slice(1), "--internal-open-vscode", record.tourPath, ctx.cwd],
          { cwd: ctx.cwd }
        );
        if (result.code !== 0) {
          ctx.ui.notify(
            `CodeTour: could not open the Tour in VS Code: ${
              result.stderr.trim() || `exit ${result.code}`
            }. Run ${command} at the workspace root.`,
            "warning"
          );
        }
      } catch (error) {
        ctx.ui.notify(
          `CodeTour: could not open the Tour in VS Code: ${
            error instanceof Error ? error.message : String(error)
          }. Run ${command} at the workspace root.`,
          "warning"
        );
      }
    }
  }

  // The window opens at the first run of the response, so a retry or a queued
  // follow-up does not hide the creations of the runs before it.
  pi.on("agent_start", () => {
    if (responseStart === undefined) {
      responseStart = Date.now();
      runCount = 0;
      runStarts = 0;
    }
    runStarts += 1;
    runUsages = [];
  });

  pi.on("agent_end", (event) => {
    runCount += 1;
    runUsages = responseUsages(event);
  });

  // `agent_settled` is Pi's final, notification-only boundary: it cannot ask
  // for a continuation, it fires once per settled response, and it is emitted
  // in print mode too. Nothing below returns a value.
  pi.on("agent_settled", async (event, ctx) => {
    const start = responseStart;
    responseStart = undefined;
    if (event?.aborted === true || start === undefined) return;
    if (reportedResponses.has(start)) return;
    reportedResponses.add(start);
    try {
      const workspace = await realWorkspace(ctx.cwd);
      if (!workspace) return;
      const { records } = await readCreations(workspace);
      const created = selectCreated(records, {
        workspace,
        sessionId: ctx.sessionManager.getSessionId(),
        since: start,
        now: Date.now(),
      }) as CreationRecord[];
      if (created.length === 0) return;
      await reportResponse(ctx, created, start);
      for (const record of created) {
        // One dialogue per Tour: a host that cannot open one still gets the
        // report, and the next Tour keeps its own offer.
        try {
          await offerReader(ctx, record, workspace);
        } catch {
          // An opening never fails the response.
        }
      }
    } catch {
      // The journal is observability only: a reading failure is never a
      // response failure and never a Tour to report.
    }
  });

  pi.registerCommand("codetour", {
    description: "Read an existing CodeTour: /codetour read [tour]; generate one: /codetour generate",
    handler: async (rawArgs, ctx) => {
      let input = rawArgs.trim();
      if (!input) {
        const choice = await ctx.ui.select("CodeTour", ["Generate", "Read"]);
        if (choice === undefined) return;
        input = choice === "Generate" ? "generate" : "read";
      }
      if (/^read(?:\s|$)/.test(input)) {
        const title = input.slice(4).trim().replace(/^(["'])(.*)\1$/, "$2");
        try {
          await readTour(pi, ctx, title);
        } catch (error) {
          ctx.ui.notify(`CodeTour: ${error instanceof Error ? error.message : String(error)}`, "error");
        }
        return;
      }
      const choices = parseChoices(input);

      let type = choices.type;
      let reviewMode = choices.reviewMode;
      if (!type) {
        const choice = await ctx.ui.select("Which tour should be generated?", [
          "Project Tour",
          "Changes Tour — Neutral",
          "Changes Tour — Critical",
        ]);
        if (!choice) {
          ctx.ui.notify("CodeTour: generation cancelled.", "info");
          return;
        }
        type = choice === "Project Tour" ? "project" : "changes";
        if (type === "changes") {
          reviewMode = choice === "Changes Tour — Critical" ? "critical" : "neutral";
        }
      }
      if (type === "changes" && !reviewMode) {
        const mode = await ctx.ui.select("Review mode", ["Neutral", "Critical"]);
        if (!mode) {
          ctx.ui.notify("CodeTour: generation cancelled.", "info");
          return;
        }
        reviewMode = mode === "Critical" ? "critical" : "neutral";
      }

      const workspace = await realWorkspace(ctx.cwd);
      if (!workspace) {
        ctx.ui.notify(`CodeTour: ${ctx.cwd} is not a usable workspace.`, "error");
        return;
      }
      // The agent creates the Tour with the installed CLI; no run state, no
      // MCP registration and nothing to release afterwards.
      try {
        pi.sendUserMessage(
          skillInvocation({
            type,
            reviewMode,
            cli: await cliForSkill(),
            request: choices.request,
          }),
          { expandPromptTemplates: true }
        );
      } catch (error) {
        ctx.ui.notify(
          `CodeTour: could not start the generation (${
            error instanceof Error ? error.message : String(error)
          }).`,
          "error"
        );
      }
    },
  });

  /** The argv words the skill must call, recorded only when the CLI is known. */
  async function cliForSkill(): Promise<string[] | undefined> {
    const launcher = await installedLauncher();
    return launcher ? cliWords(launcher) : undefined;
  }
}

